import {choose,chooseExcept,percent,loadState,spendDraw,rewardShare,STORAGE_KEY} from './engine.30d89a7cb286.js';
const $=id=>document.getElementById(id);let categories=[],sources=[],current=null,currentRound=0,busy=false,storage,state;
try{storage=window.localStorage;}catch{}state=loadState(storage);
const groupNames={Bacteria:'细菌',Archaea:'古菌',Fungi:'真菌',Protists:'原生生物',Animals:'动物',Plants:'植物'};
let toastTimer;function toast(text){$('toast').textContent=text;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),3400);}
function refresh(){if(storage)state=loadState(storage);}
function persist(){try{storage?.setItem(STORAGE_KEY,JSON.stringify(state));}catch{storage=null;toast('浏览器保存被阻止，因此计数仅在此选项卡中维护。.');}}
function updateCredits(){const previous=categories.find(c=>c.id===state.lastId);$('draw').disabled=!categories.length||busy;$('draw').textContent=previous?'查看我的生命卡 ↗':'看看我的来生 ↗';$('home-credit').textContent=state.started?`剩余 ${state.remaining} 次 · 分享可加 2 次`:'首次免费 · 可重抽 1 次';$('retry').disabled=state.remaining===0||busy;$('retry-exclude').disabled=state.remaining===0||busy||!current;$('retry').textContent=state.remaining?`再次转生 · 剩余 ${state.remaining} 次 ↻`:'重抽次数已用完';$('credit-status').textContent=`剩余 ${state.remaining} 次 · 分享可加 2 次`;$('share-rule').textContent=state.rewardedRound===currentRound?"已领取此卡的分享奖励":"每张卡奖励一次 · 发起分享或复制链接";}
function screen(view){for(const id of ['home','loading','result'])$(id).hidden=id!==view;}
function address(c){const a=["地球的深海某处","地球的蓝色海洋某处","地球的地下深处","地球的一抔土壤中","地球的某个绿色角落","地球的此时此地","地球上某个充满生命的角落"];if(['bio-04','bio-08'].includes(c.id))return a[0];if(['bio-01','bio-05'].includes(c.id))return a[2];if(['bio-03','bio-07','bio-16'].includes(c.id))return a[3];if(c.group==='Plants')return a[4];if(c.id==='bio-20')return a[5];if(c.id.startsWith('bio-24-')||['bio-02','bio-06','bio-10','bio-13-1','bio-13-2','bio-14','bio-15','bio-17','bio-18','bio-23'].includes(c.id))return a[1];return a[6];}
function motto(c){const m=["跨越难得的概率，再次成为人类。","这一次，不妨慢慢生活。","向着阳光，慢慢长出新的一章。","小小的身体，也能拥有广阔的世界。","看不见的角落，生命仍在继续。","微小的世界，也有宏大的故事。","新的身体，新的一章。"];if(c.id==='bio-20')return m[0];if(c.id==='land-mammal-12')return m[1];if(c.group==='Plants')return m[2];if(['Bacteria','Archaea'].includes(c.group))return m[3];if(c.group==='Fungi')return m[4];if(c.group==='Protists')return m[5];return m[6];}
function shareURL(c){return new URL(`r/${c.id}/?card=1`,document.baseURI).href;}
function viewResult(c,{navigate=true,round=state.round}={}){current=c;currentRound=round;$('result-name').textContent=c.name;$('result-line').textContent=motto(c);$('card-name').textContent=c.name;$('card-name').classList.toggle('long-name',c.name.length>9);$('card-latin').textContent=c.scientificName||c.group.toUpperCase();$('card-group').textContent=c.rank==='species'?`${groupNames[c.group]} · 物种级结果`:`${groupNames[c.group]} · 类群级结果`;$('card-address').textContent=address(c);$('card-probability').textContent=percent(c.probability)+'%';$('result-image').src=c.image;$('result-image').alt=c.name+(c.imageRole==='species'?'':' 类群代表图');const i=categories.indexOf(c)+1;$('specimen-id').textContent=`SPECIMEN ${String(i).padStart(3,'0')}`;$('card-number').textContent=`BIO · 2026 · ${String(i).padStart(3,'0')}`;
const s=sources.find(s=>s.categoryId===c.id);$('image-caption').textContent=s?.imageRole==='conceptual-illustration'?'AI 生成的概念插图·不是特定物种的实际照片.':c.imageRole==='species'?'物种图像和虚拟生物登记证书':`类群代表图${s?.depictedTaxon?' · '+s.depictedTaxon:''} · 并非该物种的概率`;
$('image-credit').replaceChildren();if(s){const text=document.createElement('span');text.textContent=`图像: ${s.artist||s.source} · ${s.license} · 裁剪与格式转换 `;$('image-credit').append(text);if(s.sourceUrl){const a=document.createElement('a');a.href=s.sourceUrl;a.target='_blank';a.rel='noopener';a.textContent='原始来源 ↗';$('image-credit').append(a);}if(s.licenseUrl){const a=document.createElement('a');a.href=s.licenseUrl;a.target='_blank';a.rel='noopener';a.textContent=' · 许可证 ↗';$('image-credit').append(a);}}
updateCredits();screen('result');document.title=`我的来生：${c.name} · 生命卡`;if(navigate)history.pushState({view:'result',id:c.id,round},'',shareURL(c));window.scrollTo({top:0,behavior:'smooth'});}
async function draw(retry=false,excludeCurrent=false){if(busy||!categories.length)return;refresh();if(!retry&&state.started&&state.lastId){const previous=categories.find(c=>c.id===state.lastId);if(previous){viewResult(previous);return;}}if(!spendDraw(state)){toast('如果您分享您的注册证书，将添加 2 次重播。.');return;}const excludedId=excludeCurrent?current?.id:null;const c=excludedId?chooseExcept(categories,excludedId):choose(categories);state.lastId=c.id;persist();busy=true;updateCredits();screen('loading');window.scrollTo({top:0,behavior:'smooth'});let i=0;const timer=setInterval(()=>{$('loading-name').textContent=categories[(i++*7)%categories.length].name+'，新的生命即将开始？';},140);await new Promise(r=>setTimeout(r,matchMedia('(prefers-reduced-motion: reduce)').matches?120:1900));clearInterval(timer);busy=false;viewResult(c);}
$('draw').onclick=()=>draw();$('retry').onclick=()=>draw(true);$('retry-exclude').onclick=()=>draw(true,true);$('reload').onclick=()=>location.reload();
function home({navigate=true}={}){current=null;screen('home');refresh();updateCredits();document.title='来生会是什么生命？· 来生研究所';if(navigate)history.pushState({view:'home'},'',new URL('./',document.baseURI));window.scrollTo({top:0,behavior:'smooth'});}
$('back-home').onclick=()=>home();document.querySelectorAll('.brand').forEach(a=>a.addEventListener('click',e=>{e.preventDefault();home();}));
function grantShare(round,id){refresh();if(state.round!==round||state.lastId!==id){toast('从您最近颁发的注册证书中获得奖金。.');return;}if(rewardShare(state)){persist();updateCredits();toast('分享奖金！已添加 2 次重播.');}else toast('我已经收到了这个注册证书的分享奖金。.');}
async function copy(){if(!current)return;const round=currentRound,id=current.id,url=shareURL(current);let copied=false;try{await navigator.clipboard.writeText(url);copied=true;}catch{const input=document.createElement('textarea');input.value=url;input.style.position='fixed';input.style.top='0';document.body.append(input);input.select();copied=document.execCommand('copy');input.remove();}if(copied)grantShare(round,id);else toast('复制被阻止。请复制地址栏中的链接.');}
$('copy').onclick=copy;$('share').onclick=async()=>{if(!current)return;const round=currentRound,id=current.id;const data={title:`我的来生：${current.name}`,text:`我的来生是${current.name}！概率 ${percent(current.probability)}%。你会是什么生命？`,url:shareURL(current)};if(navigator.share){try{await navigator.share(data);grantShare(round,id);}catch(e){if(e.name!=='AbortError')toast('无法打开共享窗口。请使用下面的复制链接.');}}else toast('无法在此浏览器中打开共享窗口。请使用下面的复制链接.');};
function social(network){if(!current)return;const url=encodeURIComponent(shareURL(current)),text=encodeURIComponent(`我的来生：${current.name}，概率 ${percent(current.probability)}%。你会是什么生命？`);const target=network==='x'?`https://x.com/intent/tweet?text=${text}&url=${url}`:`https://www.facebook.com/sharer/sharer.php?u=${url}`;const popup=window.open(target,'_blank','width=640,height=650');if(popup){popup.opener=null;grantShare(currentRound,current.id);}else toast('共享窗口被阻止。请使用复制链接.');}
$('share-x').onclick=()=>social('x');$('share-facebook').onclick=()=>social('facebook');$('save').onclick=()=>{if(!current)return;const a=document.createElement('a');a.href=new URL(`og/${current.id}.jpg`,document.baseURI);a.download=`next-life-${current.id}.jpg`;document.body.append(a);a.click();a.remove();toast('注册证书 JPG 我开始存钱.');};
document.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>$(b.dataset.open).showModal());document.querySelectorAll('dialog').forEach(d=>{d.querySelectorAll('.close,.dialog-close').forEach(b=>b.onclick=()=>d.close());d.addEventListener('click',e=>{if(e.target!==d)return;const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();});});
addEventListener('popstate',e=>{const c=e.state?.view==='result'?categories.find(c=>c.id===e.state.id):null;if(c)viewResult(c,{navigate:false,round:e.state.round});else home({navigate:false});});addEventListener('storage',e=>{if(e.key===STORAGE_KEY){refresh();updateCredits();}});
async function init(){screen('home');document.title='来生会是什么生命？· 来生研究所';history.replaceState({view:'home'},'',location.href);try{const responses=await Promise.all(['categories.json','image-sources.json'].map(p=>fetch(new URL(p,document.baseURI))));if(responses.some(r=>!r.ok))throw Error('Data unavailable');[categories,sources]=await Promise.all(responses.map(r=>r.json()));if(categories.length!==72)throw Error('Invalid category count');const human=categories.find(c=>c.id==='bio-20');$('human-chance').textContent='约 '+percent(human.probability)+'%';for(const id of ['land-mammal-12','bio-13-1','bio-24-5','bio-09','land-mammal-22','bio-26']){const c=categories.find(c=>c.id===id),item=document.createElement('article');item.className='sample';const img=document.createElement('img');img.src=c.image;img.alt=c.name;img.width=300;img.height=300;img.loading='lazy';const box=document.createElement('div'),h=document.createElement('h3'),small=document.createElement('small');h.textContent=c.name;small.textContent=groupNames[c.group]+' · NEXT LIFE';box.append(h,small);item.append(img,box);$('sample-strip').append(item);}updateCredits();}catch{$('draw').disabled=true;$('draw').textContent='加载信息失败';$('load-error').hidden=false;}}
init();
